<script setup>
import {ref} from 'vue';import {useRouter} from 'vue-router';import {state,t,notify} from '../state';import {api,initialize} from '../api';
const mode=ref('login'),username=ref(''),password=ref(''),visible=ref(false),busy=ref(false),error=ref(''),router=useRouter();
async function submit(){busy.value=true;error.value='';try{if(!state.ready)await initialize();if(!state.ready)throw new Error(state.sessionError);const r=await api('/auth/'+mode.value,{method:'POST',data:{username:username.value.trim(),password:password.value}});state.user=r.user;state.csrf=r.csrf;password.value='';notify(t('已登录。','Signed in.'));router.push('/evaluate');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function logout(){busy.value=true;error.value='';try{const r=await api('/auth/logout',{method:'POST',data:{}});state.user=r.user;state.csrf=r.csrf;notify(t('已退出，现以游客身份使用。','Signed out. You are now using a guest session.'));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function guest(){if(!state.ready)await initialize();if(state.ready)router.push('/evaluate');else error.value=state.sessionError;}
</script>
<template><header class="page-header"><div><h1>{{t('账户','Account')}}</h1><p>{{t('登录后保存计算记录，也可以使用游客模式。','Sign in to save your history, or continue as a guest.')}}</p></div></header>
 <section v-if="state.user&&!state.user.guest" class="panel account-panel"><h2>{{state.user.name}}</h2><p>{{t('已登录。退出后，账户内的计算记录仍会保留。','You are signed in. Your account history remains after signing out.')}}</p><div v-if="error" class="notice error" role="alert">{{error}}</div><button class="button secondary" :disabled="busy" @click="logout">{{t('退出登录','Sign out')}}</button></section>
 <section v-else class="panel account-panel"><div class="segmented" role="group" :aria-label="t('账户操作','Account action')"><button :aria-pressed="mode==='login'" :class="{selected:mode==='login'}" @click="mode='login';error=''">{{t('登录','Sign in')}}</button><button :aria-pressed="mode==='register'" :class="{selected:mode==='register'}" @click="mode='register';error=''">{{t('注册','Register')}}</button></div>
 <form @submit.prevent="submit"><label for="username">{{t('用户名','Username')}}</label><input id="username" v-model="username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+" autocomplete="username" :disabled="busy" aria-describedby="username-help"><p id="username-help" class="supporting">{{t('3–32 位字母、数字或下划线。','3–32 letters, digits or underscores.')}}</p><label for="password">{{t('密码','Password')}}</label><div class="password-field"><input id="password" v-model="password" :type="visible?'text':'password'" required minlength="8" maxlength="72" pattern="[ -~]{8,72}" :autocomplete="mode==='login'?'current-password':'new-password'" :disabled="busy" aria-describedby="password-help"><button type="button" :aria-pressed="visible" @click="visible=!visible">{{visible?t('隐藏','Hide'):t('显示','Show')}}</button></div><p id="password-help" class="supporting">{{t('8–72 个英文字符、数字或符号。','8–72 ASCII characters, digits or symbols.')}}</p><div v-if="error" class="notice error" role="alert">{{error}}</div><button class="button primary full-width" :disabled="busy">{{busy?t('请稍候…','Please wait…'):mode==='login'?t('登录','Sign in'):t('注册并登录','Register and sign in')}}</button></form>
 <p class="supporting">{{t('登录后，本次游客计算记录会保存到账户。','This guest session’s calculations will be saved to your account.')}}</p><button class="button secondary full-width" :disabled="busy" @click="guest">{{t('继续以游客使用','Continue as guest')}}</button></section>
</template>
